loginUrl:
data = ["https://www.nicelib.cc/",
"https://www.sadseas.com/",
"https://www.letsboox.com/","https://www.everjump.cc/"];

function getUrl(){
	if(!source.getVariable()||source.getVariable()==""){
		source.setVariable(JSON.stringify(data))
		}
 let 	v = JSON.parse(source.getVariable());
 let num = source.getLoginHeader();
 let length = v.length;
 if(num==length-1)num=null;
 num = Number(num??-1)+1;
 java.toast("当前接口【"+num+"】："+v[num]);
 source.putLoginHeader(num);
	}

function check(num){
	if(!source.getVariable()||source.getVariable()==""){
		source.setVariable(JSON.stringify(data))
		}
	let 	v = JSON.parse(source.getVariable());
	let n = source.getLoginHeader()??0;
	num?java.toast("当前接口【"+n+"】："+v[n]):java.toast(source.getVariable())
	}

